import fs from "node:fs";
import path from "node:path";

/**
 * The national Medicare Advantage Index: CMS Landscape data for every state,
 * 2022-2027, generated by scripts/landscape/build-us-history.py into
 * public/data/us-medicare/. index.json (statewide rows) is read on the server
 * at build time; one state's county file is fetched by the browser only when
 * someone picks that state.
 */

import type { UsIndex } from "@/lib/usMedicareIndexTypes";

export { US_DATA_PATH } from "@/lib/usMedicareIndexTypes";
export type { UsIndex, UsStateDetail, UsStateSummary } from "@/lib/usMedicareIndexTypes";

let cached: UsIndex | null = null;

/** Server only: the statewide index for all states. */
export function loadUsIndex(): UsIndex {
  if (!cached) {
    const file = path.join(process.cwd(), "public", "data", "us-medicare", "index.json");
    cached = JSON.parse(fs.readFileSync(file, "utf8")) as UsIndex;
  }
  return cached;
}

export interface StateChange {
  code: string;
  name: string;
  fromYear: number;
  from: number;
  to: number;
  pct: number;
}

/** Change in the typical out-of-pocket max from each state's first reported year to the last. */
export function moopChanges(index: UsIndex): StateChange[] {
  const last = index.years[index.years.length - 1];
  const out: StateChange[] = [];
  for (const [code, s] of Object.entries(index.states)) {
    const fromYear = index.years.find((y) => s.statewide[String(y)]?.moopMedian != null);
    const from = fromYear ? s.statewide[String(fromYear)].moopMedian : null;
    const to = s.statewide[String(last)]?.moopMedian ?? null;
    if (!fromYear || from == null || to == null || fromYear === last) continue;
    out.push({
      code,
      name: s.name,
      fromYear,
      from,
      to,
      pct: Math.round(((to - from) / from) * 100),
    });
  }
  return out.sort((a, b) => b.pct - a.pct);
}
